    type HTMLAttributes with
        [<Erase; LanguageInjection(InjectedLanguage.HTML)>]
        member _.innerHTML
            with set (_: string) = ()
            and [<Erase>] get (): string = unbox ()

        [<Erase; LanguageInjection("jsx", Prefix = "<div textContent='", Suffix = "' >")>]
        member _.textContent
            with set (_: string) = ()
            and [<Erase>] get (): string = unbox ()

        [<Erase>]
        member _.autofocus
            with set (_: bool) = ()
            and [<Erase>] get (): bool = unbox ()

        /// <summary>
        /// Class names to apply. Accepts a string, an object whose keys are class
        /// names and values are booleans (`{ active: isActive() }` — truthy keys
        /// are added), or an array merging strings/objects/nested arrays
        /// (`["card", props.class, { active: isActive() }]`).
        ///
        /// For conditional classes, prefer the array+object form. Don't build
        /// class strings manually with concatenation, template literals, or
        /// `.filter(Boolean).join(" ")` — that's the React/`classnames` reflex
        /// and the array+object form replaces it. The array+object form composes
        /// with reactive values directly; manually-built strings re-run the whole
        /// concatenation on every change instead of toggling the affected classes.
        /// </summary>
        [<Erase; LanguageInjection("jsx", Prefix = "<div class='", Suffix = "' >")>]
        member _.class'
            with set (_: string) = ()
            and [<Erase>] get (): string = unbox ()

        [<Erase; LanguageInjection("jsx", Prefix = "<div elementtiming='", Suffix = "' >")>]
        member _.elementtiming
            with set (_: string) = ()
            and [<Erase>] get (): string = unbox ()

        [<Erase; LanguageInjection("jsx", Prefix = "<div id='", Suffix = "' >")>]
        member _.id
            with set (_: string) = ()
            and [<Erase>] get (): string = unbox ()

        [<Erase; LanguageInjection("jsx", Prefix = "<div nonce='", Suffix = "' >")>]
        member _.nonce
            with set (_: string) = ()
            and [<Erase>] get (): string = unbox ()

        [<Erase; LanguageInjection("jsx", Prefix = "<div part='", Suffix = "' >")>]
        member _.part
            with set (_: string) = ()
            and [<Erase>] get (): string = unbox ()

        [<Erase; LanguageInjection("jsx", Prefix = "<div slot='", Suffix = "' >")>]
        member _.slot
            with set (_: string) = ()
            and [<Erase>] get (): string = unbox ()

        [<Erase>]
        member _.tabindex
            with set (_: int) = ()
            and [<Erase>] get (): int = unbox ()

        [<Erase; LanguageInjection("jsx", Prefix = "<div innerText='", Suffix = "' >")>]
        member _.innerText
